// ── Day tracking ──────────────────────────────────────────────────────────────
// Count Monday–Friday days between two UTC dates (end is exclusive).
function countWeekdays(startDate, endDate) {
  let count = 0;
  const current = new Date(startDate);
  current.setUTCHours(0, 0, 0, 0);
  const end = new Date(endDate);
  end.setUTCHours(0, 0, 0, 0);

  while (current < end) {
    const dow = current.getUTCDay();
    if (dow !== 0 && dow !== 6) count++;
    current.setUTCDate(current.getUTCDate() + 1);
  }
  return count;
}

// Rotation anchor.
// The deck grew from 63 to 112 days. Because the index is `elapsed % DAYS.length`,
// changing the length would have jumped the counter from "Day 16 of 63" straight to
// "Day 79 of 112" on the next send. Anchoring the sequence to a known (date, day)
// pair keeps it continuous — and, unlike START_DATE, it stays correct the next time
// days are added, because the anchor can simply be restamped to the last send.
// Anchor: with the old 63-day deck and the retired START_DATE=2026-05-19, there
// were 77 elapsed weekdays on 2026-09-03 and 77 % 63 = 14, i.e. that day's send was
// "Day 15 of 63". The anchor continues from exactly there.
// The deck is now 122 days (63 -> 112 -> 117 -> 122).
// WHEN A RESTAMP IS ACTUALLY NEEDED. The invariant is not "length changed" — it is
// that (date, dayNumber) must name a real past send whose number was NOT produced by
// a wrap under the old modulus. If the anchor still satisfies that, growing
// DAYS.length is safe on its own: the sequence only diverges from the old deck at the
// old wrap point, which is precisely where the new days should start appearing.
// Wave 2 (117 -> 122, Sept 2026) therefore did NOT restamp, and that was verified by
// simulating getTodayIndex() over 400 days under both lengths: Mon 2026-09-07 renders
// Day 17 either way, the printed counter never jumps or repeats, and days 118-122
// first send 2027-01-26 through 2027-02-01 — the old 117-deck wrap point.
// So: restamp only if the anchor is stale or sits after a wrap. Restamping an
// already-correct anchor MOVES the counter and is itself the bug.
const ROTATION_ANCHOR = { date: "2026-09-04", dayNumber: 16 };

function getTodayIndex() {
  const today = new Date();
  today.setUTCHours(0, 0, 0, 0);
  // countWeekdays returns 0 when today is on or before the anchor date.
  const elapsed = countWeekdays(new Date(ROTATION_ANCHOR.date), today);
  return (ROTATION_ANCHOR.dayNumber - 1 + elapsed) % DAYS.length;
}

// ── Email HTML ────────────────────────────────────────────────────────────────
function buildEmail(day, dayNumber, total) {
  const { domain, taskCode, concept, research, application, questions } = day;

  const bodyParagraphs = concept.body
    .split("\n\n")
    .map(
      (p) =>
        `<p style="margin:0 0 14px;line-height:1.7;color:#333;">${p}</p>`
    )
    .join("");

  const questionsHtml = questions
    .map((q, i) => {
      const optionsHtml = q.options
        .map((opt) => `<li style="margin:6px 0;color:#333;">${opt}</li>`)
        .join("");

      return `
        <div style="margin-bottom:24px;">
          <p style="margin:0 0 10px;font-weight:bold;color:#333;">${i + 1}. ${q.q}</p>
          <ul style="margin:0;padding-left:20px;list-style:none;">${optionsHtml}</ul>
        </div>`;
    })
    .join("");

  const answersHtml = questions
    .map((q, i) => `
        <div style="margin-bottom:20px;">
          <p style="margin:0 0 6px;font-weight:bold;color:#333;">${i + 1}. ${q.answer}</p>
          <p style="margin:0;font-style:italic;color:#555;font-size:14px;"><strong>Rationale:</strong> ${q.rationale}</p>
        </div>`)
    .join("");

  return `<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
</head>
<body style="margin:0;padding:24px;background:#e8e3db;font-family:Georgia,serif;">
  <div style="max-width:620px;margin:0 auto;background:#f8f5f0;border-radius:8px;overflow:hidden;">

    <!-- Header -->
    <div style="background:#c8440a;padding:20px 28px;">
      <p style="margin:0;color:#fff;font-size:13px;letter-spacing:0.05em;">
        BCBA Daily Brief &nbsp;&middot;&nbsp; Day ${dayNumber} of ${total}
      </p>
      <p style="margin:6px 0 0;color:#fff;font-size:13px;line-height:1.5;opacity:0.92;">
        Test Content Outline (6th ed.) &nbsp;&middot;&nbsp; ${domain} &nbsp;&middot;&nbsp; ${taskCode}
      </p>
    </div>

    <!-- Body -->
    <div style="padding:28px;">

      <!-- Concept -->
      <h2 style="margin:0 0 16px;color:#c8440a;font-size:20px;">${concept.title}</h2>
      ${bodyParagraphs}

      <!-- Research Citation -->
      <div style="margin:24px 0;padding:16px;background:#fff;border-left:4px solid #c8440a;border-radius:0 4px 4px 0;">
        <p style="margin:0 0 10px;font-style:italic;color:#c8440a;font-size:14px;">${research.citation}</p>
        <p style="margin:0;line-height:1.7;color:#333;">${research.summary}</p>
      </div>

      <!-- Clinical Application -->
      <h3 style="margin:24px 0 12px;color:#c8440a;font-size:16px;">Clinical Application</h3>
      <p style="margin:0 0 24px;line-height:1.7;color:#333;">${application}</p>

      <!-- Practice Questions -->
      <h3 style="margin:0 0 16px;color:#c8440a;font-size:16px;">Practice Questions</h3>
      ${questionsHtml}

      <!-- Answers divider -->
      <div style="margin-top:320px;padding-top:24px;border-top:2px solid #c8440a;text-align:center;">
        <p style="margin:0;font-size:15px;font-weight:bold;color:#c8440a;letter-spacing:0.05em;">— Answers Below —</p>
      </div>

      <!-- Answers -->
      <div style="margin-top:24px;">
        ${answersHtml}
      </div>

    </div>

    <!-- Footer -->
    <div style="padding:16px 28px;background:#e0dbd3;border-top:1px solid #cec8c0;">
      <p style="margin:0;font-size:12px;color:#777;">
        Day ${dayNumber} &nbsp;&middot;&nbsp; ben@voxprint.com &nbsp;&middot;&nbsp; Reply STOP to unsubscribe
      </p>
    </div>

  </div>
</body>
</html>`;
}

// ── Route handler ─────────────────────────────────────────────────────────────
export async function GET(req) {
  // Verify Vercel's cron secret.
  if (
    req.headers.get("authorization") !==
    "Bearer " + process.env.CRON_SECRET
  ) {
    return new Response("Unauthorized", { status: 401 });
  }

  const index = getTodayIndex();
  const day = DAYS[index];
  const dayNumber = index + 1;

  const html = buildEmail(day, dayNumber, DAYS.length);

  const { error } = await resend.emails.send({
    from: "BCBA Daily Brief <bcba@voxprinting.com>",
    to: ["ben@voxprint.com", "kadiblack17@gmail.com", "Tara@sandstoneaba.org", "Hannah@sandstoneaba.org"],
    subject: `BCBA Daily Brief — Day ${dayNumber}: ${day.concept.title}`,
    html,
  });

  if (error) {
    console.error("Resend error:", error);
    return new Response("Email send failed", { status: 500 });
  }

  return new Response(
    JSON.stringify({ ok: true, day: dayNumber, concept: day.concept.title }),
    { status: 200, headers: { "Content-Type": "application/json" } }
  );
}
